import * as THREE from "three";

/**
 * Triplanar detail texturing. Every library material (MAT_*) keeps its vertex-colour palette and gains a
 * tileable grey "detail" albedo (multiplied, mean-preserving) plus a detail normal map, both generated by
 * blender/scripts/build_textures.py. Projection is in world space for static meshes (so instanced walls do not
 * repeat identically) and in bind-pose object space for skinned characters (so the grain does not swim).
 * No UVs are required.
 */

export interface DetailSpec {
  set: string;
  scale: number; // texture repeats per metre
  albedo: number; // 0 = off, 1 = full contrast
  normal: number;
  roughness?: number; // +/- roughness variation driven by the detail
}

export const DETAIL_SPECS: Record<string, DetailSpec> = {
  MAT_Stone_Granite_A: { set: "stone", scale: 0.55, albedo: 0.85, normal: 0.55, roughness: 0.12 },
  MAT_Plaster_Lime_A: { set: "plaster", scale: 0.35, albedo: 0.8, normal: 0.3, roughness: 0.06 },
  MAT_Wood_Teak_A: { set: "wood", scale: 1.1, albedo: 0.9, normal: 0.45, roughness: 0.1 },
  MAT_Terracotta_A: { set: "terracotta", scale: 1.4, albedo: 0.7, normal: 0.4, roughness: 0.08 },
  MAT_Thatch_A: { set: "thatch", scale: 1.6, albedo: 1.0, normal: 0.8, roughness: 0.05 },
  MAT_Soil_A: { set: "soil", scale: 0.9, albedo: 0.9, normal: 0.6, roughness: 0.03 },
  MAT_Foliage_A: { set: "foliage", scale: 2.0, albedo: 0.55, normal: 0.35 },
  MAT_Cloth_A: { set: "cloth", scale: 4.0, albedo: 0.5, normal: 0.35 },
  MAT_Brass_A: { set: "brass", scale: 2.5, albedo: 0.6, normal: 0.25, roughness: 0.15 },
  MAT_Skin_A: { set: "skin", scale: 4.0, albedo: 0.35, normal: 0.12 },
  MAT_Brick_A: { set: "brick", scale: 0.85, albedo: 0.9, normal: 0.7, roughness: 0.06 },
  GROUND: { set: "ground", scale: 0.28, albedo: 0.85, normal: 0.4 },
};

const loader = new THREE.TextureLoader();
const cache = new Map<string, { albedo: THREE.Texture; normal: THREE.Texture }>();
let anisotropy = 4;
let enabled = true;

export function configureDetail(opts: { anisotropy: number; enabled: boolean }): void {
  anisotropy = opts.anisotropy;
  enabled = opts.enabled;
}

function textures(set: string) {
  let t = cache.get(set);
  if (!t) {
    const load = (kind: string) => {
      const tex = loader.load(`/assets/textures/detail/${set}_${kind}.jpg`, undefined, undefined, () => console.warn(`[detail] missing ${set}_${kind}`));
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      tex.colorSpace = THREE.NoColorSpace;
      tex.anisotropy = anisotropy;
      return tex;
    };
    t = { albedo: load("albedo"), normal: load("normal") };
    cache.set(set, t);
  }
  return t;
}

const VERT_DECL = /* glsl */ `
varying vec3 vTomPos;
varying vec3 vTomNormal;
#ifdef TOM_OBJECT_SPACE
varying mat3 vTomBasis;
#endif
`;

const VERT_BODY = /* glsl */ `
#ifdef TOM_OBJECT_SPACE
  vTomPos = position;
  vTomNormal = normal;
  vTomBasis = mat3(modelMatrix);
#else
  vec4 tomP = vec4(transformed, 1.0);
  vec3 tomN = objectNormal;
  #ifdef USE_INSTANCING
    tomP = instanceMatrix * tomP;
    tomN = mat3(instanceMatrix) * tomN;
  #endif
  vTomPos = (modelMatrix * tomP).xyz;
  vTomNormal = normalize(mat3(modelMatrix) * tomN);
#endif
`;

const FRAG_DECL = /* glsl */ `
varying vec3 vTomPos;
varying vec3 vTomNormal;
#ifdef TOM_OBJECT_SPACE
varying mat3 vTomBasis;
#endif
uniform sampler2D tomAlbedo;
uniform sampler2D tomNormalMap;
uniform float tomScale;
uniform float tomAlbedoStrength;
uniform float tomNormalStrength;
uniform float tomRoughness;
`;

const FRAG_COLOR = /* glsl */ `
  vec3 tomW = pow(abs(normalize(vTomNormal)), vec3(4.0));
  tomW /= (tomW.x + tomW.y + tomW.z + 1e-5);
  vec2 tomUvX = vTomPos.zy * tomScale;
  vec2 tomUvY = vTomPos.xz * tomScale;
  vec2 tomUvZ = vTomPos.xy * tomScale;
  float tomD = texture2D(tomAlbedo, tomUvX).r * tomW.x + texture2D(tomAlbedo, tomUvY).r * tomW.y + texture2D(tomAlbedo, tomUvZ).r * tomW.z;
  diffuseColor.rgb *= clamp(1.0 + (tomD - 0.5) * 2.0 * tomAlbedoStrength, 0.25, 1.75);
`;

const FRAG_ROUGH = /* glsl */ `
  roughnessFactor = clamp(roughnessFactor + (0.5 - tomD) * tomRoughness, 0.04, 1.0);
`;

const FRAG_NORMAL = /* glsl */ `
  {
    vec3 tnX = texture2D(tomNormalMap, tomUvX).xyz * 2.0 - 1.0;
    vec3 tnY = texture2D(tomNormalMap, tomUvY).xyz * 2.0 - 1.0;
    vec3 tnZ = texture2D(tomNormalMap, tomUvZ).xyz * 2.0 - 1.0;
    vec3 tomPert = vec3(0.0, tnX.y, tnX.x) * tomW.x + vec3(tnY.x, 0.0, tnY.y) * tomW.y + vec3(tnZ.x, tnZ.y, 0.0) * tomW.z;
    #ifdef TOM_OBJECT_SPACE
      tomPert = vTomBasis * tomPert;
    #endif
    normal = normalize(normal + (viewMatrix * vec4(tomPert, 0.0)).xyz * tomNormalStrength);
  }
`;

/** Patch a MeshStandardMaterial in place. Safe to call more than once. */
export function applyDetail(material: THREE.Material, specKey: string, objectSpace: boolean): void {
  const spec = DETAIL_SPECS[specKey];
  const m = material as THREE.MeshStandardMaterial;
  if (!enabled || !spec || !m.isMeshStandardMaterial || m.userData.tomDetail) return;
  const tex = textures(spec.set);
  m.userData.tomDetail = specKey;
  m.defines = { ...(m.defines ?? {}), ...(objectSpace ? { TOM_OBJECT_SPACE: "" } : {}) };
  m.customProgramCacheKey = () => `tom-${specKey}-${objectSpace ? "o" : "w"}`;
  m.onBeforeCompile = (shader) => {
    shader.uniforms.tomAlbedo = { value: tex.albedo };
    shader.uniforms.tomNormalMap = { value: tex.normal };
    shader.uniforms.tomScale = { value: spec.scale };
    shader.uniforms.tomAlbedoStrength = { value: spec.albedo };
    shader.uniforms.tomNormalStrength = { value: spec.normal };
    shader.uniforms.tomRoughness = { value: spec.roughness ?? 0 };
    shader.vertexShader = VERT_DECL + shader.vertexShader.replace("#include <project_vertex>", `#include <project_vertex>\n${VERT_BODY}`);
    shader.fragmentShader =
      FRAG_DECL +
      shader.fragmentShader
        .replace("#include <color_fragment>", `#include <color_fragment>\n${FRAG_COLOR}`)
        .replace("#include <roughnessmap_fragment>", `#include <roughnessmap_fragment>\n${FRAG_ROUGH}`)
        .replace("#include <normal_fragment_maps>", `#include <normal_fragment_maps>\n${FRAG_NORMAL}`);
  };
  m.needsUpdate = true;
}
